```cpp
#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    if (n == 1) {
        cout << 1 << "\n";
        return 0;
    }

    if (n == 2) {
        cout << -1 << "\n";
        return 0;
    }

    // Construção do vetor base v de tamanho n cuja média é um de seus elementos
    vector<long long> v(n);
    if (n % 2 != 0) {
        for (int i = 0; i < n; ++i) {
            v[i] = i + 1;
        }
    } else {
        long long sum = 0;
        for (int i = 0; i < n - 1; ++i) {
            v[i] = i + 1;
            sum += v[i];
        }
        // A média será v[n - 2] = n - 1
        v[n - 1] = (long long)n * (n - 1) - sum;
    }

    // M é escolhido maior que max(v) - min(v) para garantir unicidade dos valores
    long long M = v[n - 1];

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            long long val = M * v[i] + v[j];
            cout << val << (j == n - 1 ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}
```

